{
  "watch1": {
    "scenarios": [
      "features/no-todos.feature:Main section and footer are hidden when there are no todos",
      "features/new-todo.feature:Adding a new todo via the input",
      "features/new-todo.feature:Empty input is ignored",
      "features/new-todo.feature:Input is trimmed before creating"
    ]
  },
  "watch2": {
    "scenarios": [
      "features/toggle-all.feature:Toggle all marks every todo as completed",
      "features/toggle-all.feature:Unchecking toggle all marks every todo as active",
      "features/toggle-all.feature:Toggle all reflects individual state changes"
    ]
  },
  "watch3": {
    "scenarios": [
      "features/item.feature:Checking a todo marks it as completed",
      "features/item.feature:Unchecking a todo marks it as active",
      "features/item.feature:Destroying a todo removes it from the list"
    ]
  },
  "watch4": {
    "scenarios": [
      "features/editing.feature:Double-clicking activates edit mode",
      "features/editing.feature:Pressing Enter saves the edit",
      "features/editing.feature:Blurring saves the edit",
      "features/editing.feature:Empty edit destroys the todo",
      "features/editing.feature:Escape discards changes"
    ]
  },
  "watch5": {
    "scenarios": [
      "features/counter.feature:Counter shows zero with no todos",
      "features/counter.feature:Counter shows singular for one item",
      "features/counter.feature:Counter shows plural for multiple items",
      "features/counter.feature:Counter reflects only active todos"
    ]
  },
  "watch6": {
    "scenarios": [
      "features/clear-completed.feature:Clear completed removes finished todos",
      "features/clear-completed.feature:Clear completed button is hidden when no todos are completed",
      "features/clear-completed.feature:Clear completed button is visible when todos are completed"
    ]
  },
  "watch7": {
    "scenarios": [
      "features/persistence.feature:Todos persist after reload",
      "features/persistence.feature:Completed state persists after reload"
    ]
  },
  "watch8": {
    "scenarios": [
      "features/routing.feature:Default route shows all todos",
      "features/routing.feature:Active filter shows only incomplete todos",
      "features/routing.feature:Completed filter shows only done todos",
      "features/routing.feature:Filter link is selected based on current route"
    ]
  }
}

